def generate_headers(cfg, manifest):
    html_dir = os.path.join(WORK_ROOT, str(cfg["id"]), "headers_html")
    png_dir = os.path.join(WORK_ROOT, str(cfg["id"]), "headers_png")
    webp_dir = os.path.join(WORK_ROOT, str(cfg["id"]), "headers_webp")
    for path in (html_dir, png_dir, webp_dir):
        os.makedirs(path, exist_ok=True)
    lesson_ids = []
    for sec in manifest["sections"]:
        for lesson in sec["lessons"]:
            lid = lesson["id"]
            with open(os.path.join(html_dir, f"header-{lid}.html"), "w", encoding="utf-8") as f:
                f.write(header_html(lesson["label"], lesson["title"]))
            lesson_ids.append(lid)
    subprocess.run(["node", os.path.join(ROOT, "scripts", "render_batch.mjs"), html_dir, png_dir, "1920", "420"], check=True)
    urls = {}
    for lid in lesson_ids:
        png = os.path.join(png_dir, f"header-{lid}.png")
        webp = os.path.join(webp_dir, f"header-{lid}.webp")
        subprocess.run(["cwebp", "-q", "82", png, "-o", webp], check=True, stdout=subprocess.DEVNULL)
        url, _ = upload_attachment(str(cfg["id"]), webp, f"header-{lid}.webp")
        urls[lid] = url
        print(f"header {lid} -> {url}")
    return urls


def link_block(keys):
    return "<h3>Полезные ссылки</h3><ul>" + "".join(f'<li><a href="{e(LINKS[k][1])}">{e(LINKS[k][0])}</a></li>' for k in keys) + "</ul>"


def lesson_html(cfg, header_url, lesson_data, workbook_url=None):
    title, _, intro, practical, transition, *rest = lesson_data
    kind = rest[0] if rest and isinstance(rest[0], str) else None
    keys = rest[0] if rest and isinstance(rest[0], list) else rest[1] if len(rest) > 1 else ["wb_help", "ozon_help", "ozon_university"]
    workbook = f'<p><strong>Файл-практикум:</strong> <a href="{e(workbook_url)}">Marketplace-Praktikum-183098.xlsx</a>.</p>' if workbook_url else ""
    context = "Каждый урок привязан к одной карточке товара: вы не просто читаете теорию, а решаете, что именно менять в карточке, рекламе, цене, отзывах или остатках." if workbook_url else "Каждый урок привязан к практическому вопросу: где карточка теряет покупателя и какое решение можно принять без догадок."
    return f"""<p><img src="{e(header_url)}" alt="{e(title)}"></p>
<h2>Что будет на уроке?</h2>
<p>{e(intro)}</p>
<p>{context}</p>
{workbook}
<h3>Как применять</h3>
<p>{e(practical)}</p>
<p>Запишите вывод письменно: товар, проблема, доказательство, действие и метрика проверки. Такой формат защищает от типичной ошибки — спорить о вкусе фотографии или описания, когда нужно смотреть на воронку, экономику и поведение покупателя.</p>
<ul>
  <li>Привязывайте вывод к конкретной карточке, а не ко всей площадке сразу.</li>
  <li>Проверяйте экономику до увеличения бюджета.</li>
  <li>Меняйте один крупный элемент за раз, если хотите понять эффект.</li>
  <li>Смотрите не только на заказы, но и на выкупы, возвраты, ДРР и маржу.</li>
</ul>
<p><strong>Частая ошибка:</strong> считать маркетплейс набором лайфхаков. Рабочий результат появляется не от одного трюка, а от связки: товар, спрос, карточка, цена, доверие, наличие, реклама и регулярный отчёт.</p>
<h3>Что дальше?</h3>
<p>{e(transition)}</p>
{link_block(keys)}
"""


